import sys
from collections import deque

data = sys.stdin.read().split()
n = int(data[0])
d = tuple(int(data[1 + n + i]) - int(data[1 + i]) for i in range(n))
LIM = 3
start = d
goal = tuple([0] * n)
dist = {start: 0}
q = deque([start])
while q:
    s = q.popleft()
    if s == goal:
        break
    for l in range(n):
        for r in range(l, n):
            for delta in (1, -1):
                t = list(s)
                for i in range(l, r + 1):
                    t[i] += delta
                if max(t) > LIM or min(t) < -LIM:
                    continue
                t = tuple(t)
                if t not in dist:
                    dist[t] = dist[s] + 1
                    q.append(t)
print(dist[goal])

